@dataclass
class Order:
    id: str
    total_cents: int

    @property
    def total_euros(self) -> float:
        return self.total_cents / 100

    def with_discount(self, percent: int) -> "Order":
        return Order(
            id=self.id,
            total_cents=self.total_cents * (100 - percent) // 100,
        )

